push("🌹分类🌹",null,1)
    for(i in a){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.25;
  url=String(url).replace("1.html","{{page}}.html").replace("1/","{{page}}/")
        push(title,url,size)
    };

push("🌹排行🌹",null,1)
    for(i in b){
        title=b[i].text()
        url=b[i].attr("href")
  url=String(url).replace(".htm","<,_{{page}}>.htm")
        size=0.25;
        push(title,url,size)
    }


 push("🌹全本🌹","/full-{{page}}/",1)
    for(i in c){
        title=c[i].text()
        url=c[i].attr("href")
  url=String(url).replace(".htm","<,_{{page}}>.htm")
        size=0.25;
        push(title,url,size)
    }

}else{
  java.toast("发现列表获取失败！")
}

